Rules are stored in the hot database. Edit via the Rules tab in the UI or add programmatically:

```rust
use crate::alert_rules::CustomRule;

let rule = CustomRule {
    name: "Suspicious DNS Query".to_string(),
    description: "Detects queries to known malicious domains".to_string(),
    conditions: vec![
        RuleCondition::ProtocolEquals("UDP".to_string()),
        RuleCondition::PortEquals(53),
    ],
    severity: "HIGH".to_string(),
    enabled: true,
};

save_custom_rule(&rule)?;
```"}]

